import { MENU_SECTIONS, isLeaf, sectionHref } from '@/lib/nav-tree'

/** Every in-page tab, for the app search. Generated by reading each page; keep in step when a tab is added. */
export type TabEntry = {
  label: string
  page: string
  to: string
  exact: boolean
  keywords?: string
  /** Shown only to managers / admins, as the tab itself is. */
  managerOnly?: boolean
  adminOnly?: boolean
}

/*
 * How each page reads its tab (so a `to` here actually lands on it):
 * - useTab (src/lib/useTab.ts): `?tab=<key>` — Harvest, Calculator, Checklists, Chemicals, Spraying, Seed & planter, Combine,
 *   Cattle (Pastures /cattle, Herd /herd, Feed /feed, Sales & paperwork /cattle-markets),
 *   Contracts, Markets, Hauling, Map, Meeting, Plan, Utilities, Fertilizer, Weather, Turbines.
 * - River (/river): `?tab=home-ranch|east-ranch|map` (lib/river.ts); none follows the main ranch.
 * - QuickBooks: `?tab=<key>` read directly.
 * - Fertilizer: five routes since 24 Oct 2026 (/fertilizer/soil, /plan, /prices, /manure,
 *   /savings), each with useTab `?tab=<key>` (src/lib/fertilizer-views.ts). Old
 *   `/fertilizer?tab=<old key>` links redirect.
 * - Irrigation (AIMM, /irrigation): `?view=overview|detail|setup`.
 * - Irrigation info (/irrigation-info): `?tab=pump` (anything else is Pivot Information).
 * - Settings: four views since 24 Oct 2026 — /settings/account, /settings/people,
 *   /settings/connections, /settings/farm — each with useTab's `?tab=<key>`
 *   (lib/settings-routes.ts). Old /settings?tab=/section=/part= links still forward.
 * - Tasks, Checklists, Calendar and Monthly jobs are each their own route and view.
 * Spaces in tab keys are left unencoded, the way src/lib/tiles.ts writes them.
 */
